function draw() {
  background(255);

  let imgAspectRatio = img.width / img.height;

  let newWidth = width;
  let newHeight = newWidth / imgAspectRatio;

  if (newHeight > height) {
    newHeight = height;
    newWidth = newHeight * imgAspectRatio;
  }

  let x = (width - newWidth) / 2;
  let y = (height - newHeight) / 2;

  image(img, x, y, newWidth, newHeight);
}


